function experimentSortKey(id){const final=id.startsWith('F')?1:0;const nums=(id.match(/\d+/g)||[]).map(Number);return [final,...nums]}
function compareExperiment(a,b){const A=experimentSortKey(a.id),B=experimentSortKey(b.id);for(let i=0;i<Math.max(A.length,B.length);i++){const d=(A[i]??-1)-(B[i]??-1);if(d)return d}return a.id.localeCompare(b.id)}
function experimentPhase(x){
  const id=String(x?.id||'');
  if(currentExp==='navigation'){
    const n=Number((id.match(/^N(\d+)/)||[])[1]);
    if(Number.isFinite(n)){if(n<=6)return'foundation';if(n<=9)return'localization';if(n<=15)return'autonomy';return'certification'}
    return'bab4';
  }
  if(currentExp==='perception'){
    if(id.startsWith('F'))return'final';const m=Number((id.match(/^4\.(\d+)/)||[])[1]);
    if(m<=2)return'pipeline';if(m===3)return'calibration';if(m<=5)return'scene';if(m<=7)return'safety';return'validation';
  }
  const m=Number((id.match(/^4\.(\d+)/)||[])[1]);
  if(m<=2)return'setup';if(m===3)return'foc';if(m<=5)return'outer';if(m<=8)return'dynamics';return'final';
}
