function navigationReportList(){
  const src=experiments.navigation||[],byId=id=>src.find(x=>x.id===id);
  return navigationReportBlueprints().map(bp=>{const ss=bp.sources.map(byId).filter(Boolean);if(!ss.length)return null;const dedupe=(arr,keyFn)=>{const seen=new Set();return arr.filter(v=>{const k=keyFn(v);if(seen.has(k))return false;seen.add(k);return true})};let fields=dedupe(ss.flatMap(x=>x.parameterFields||[]),p=>`${p.yamlFileKey||''}:${p.yamlPath||p.key||p.label}`);if(bp.fieldKeys)fields=fields.filter(p=>bp.fieldKeys.includes(String(p.key||'')));if(bp.freeze)fields=fields.map(p=>p.yamlFileKey?{...p,kind:'yaml_readonly',locked:true,group:p.group||'FROZEN CONFIG'}:p);const graphCaptions=bp.graphCaptions||ss.flatMap(x=>x.graphCaptions||[]),graphs=bp.graphs||ss.flatMap(x=>x.graphs||[]),liveSeries=bp.liveSeries||Object.assign({},...ss.map(x=>x.liveSeries||{}));return {id:bp.id,groupId:bp.group,groupTitle:bp.group,section:`${bp.id.slice(1)} ${bp.title}`,reportMode:true,sourceIds:bp.sources,parameterFields:fields,tableColumns:bp.tables||ss.flatMap(x=>x.tableColumns||[]),tableNames:bp.tableNames||ss.flatMap(x=>x.tableNames||[]),graphCaptions,graphs,liveSeries}}
  ).filter(Boolean)
}
function findExperimentById(id){return (experiments[currentExp]||[]).find(v=>v.id===id)||(currentExp==='navigation'?navigationReportList().find(v=>v.id===id):null)}
function displayExperimentId(x){const id=String(x?.id||'');let m;if((m=id.match(/^R(4\.\d+\.\d+)$/)))return m[1];if((m=id.match(/^N(\d+)\.(\d+)$/)))return `${+m[1]}.${+m[2]}`;if((m=id.match(/^4\.(\d+)\.(\d+)$/)))return `${+m[1]}.${+m[2]}`;if((m=id.match(/^4\.(\d+)$/)))return `${+m[1]}.1`;if((m=id.match(/^F4\.(\d+)$/)))return `Final ${+m[1]}.1`;return id.replace(/^N(?=\d)/,'')}
function reportRunId(x=selectedExperiment,domain=currentExp){const id=String(x?.id||'').trim();if(domain==='navigation'){if(/^R4\.[1-4]\.[1-3]$/.test(id))return `BAB4_${displayExperimentId(x)}`;return /^N\d+\.\d+$/.test(id)?id:`N${displayExperimentId(x)}`}let d=displayExperimentId(x).replace(/^Final\s+/i,'').replace(/[^0-9.]/g,'');if(!d)d='0.0';return (domain==='perception'?'P':'E')+d}
function stripCatalogPrefix(text=''){return String(text).replace(/^FINAL BAB IV\s*[—-]\s*/i,'').replace(/^N\d+(?:\.\d+)?\s+/,'').replace(/^4\.\d+(?:\.\d+)?\s+/,'').trim()}
